mapper.select:
SELECT * FROM score_record
WHERE user_id = #{userId}

    AND DATE_FORMAT(create_time, '%Y-%m') = #{month}

ORDER BY create_time DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COALESCE(SUM(CASE WHEN change_type = 1 THEN change_amount ELSE 0 END), 0) AS earned,
       COALESCE(SUM(CASE WHEN change_type = 2 THEN -change_amount ELSE 0 END), 0) AS spent,
       COALESCE(SUM(CASE WHEN change_type = 3 THEN change_amount ELSE 0 END), 0) AS refunded
FROM score_record WHERE user_id = #{userId}
  AND create_time >= #{start} AND create_time < #{end}
